func (q *Queries) RetainAppConfigGuardSecret(ctx context.Context, db DBTX, arg RetainAppConfigGuardSecretParams) error {
	_, err := db.Exec(ctx, retainAppConfigGuardSecret,
		arg.GuardID,
		arg.ConfigKey,
		arg.AccountID,
		arg.AppID,
		arg.Scope,
	)
	return err
}
